add_filter( 'woocommerce_cart_shipping_method_full_label', 'perfectpixel_zero_free_shipping_label', 10, 2 );
add_filter( 'woocommerce_order_shipping_to_display', 'perfectpixel_zero_free_shipping_order', 10, 2 );

function perfectpixel_zero_free_shipping_label( $label, $method ) {
	if ( 0.0 === (float) $method->get_cost() && false === strpos( $label, 'amount' ) ) {
		$label .= ': ' . wc_price( 0 );
	}
	return $label;
}

function perfectpixel_zero_free_shipping_order( $shipping, $order ) {
	if ( 0.0 === (float) $order->get_shipping_total() && $order->get_shipping_methods() && false === strpos( $shipping, 'amount' ) ) {
		$shipping = wc_price( 0, array( 'currency' => $order->get_currency() ) ) . ' ' . $shipping;
	}
	return $shipping;
}
